import csv, math
from pathlib import Path
src=Path('outputs/expanded_22_candidate_risk_gene_table.csv')
rows=list(csv.DictReader(src.open(newline='')))
fields=['variant','higher_mvp_insomnia_allele','comparison_allele','nearest_gene_body_positional','mvp_insomnia_or_approx','mvp_insomnia_p','hfrs_beta','hfrs_se','hfrs_p','fi_beta','fi_p','ffs_beta','ffs_p','ukb_insomnia_beta','ukb_insomnia_p','all_five_nominal','reference_alleles','in_original_15']
result=[]
for r in rows:
    s=1 if float(r['MVP_insomnia_log_OR_aligned_from_rounded_OR'])>0 else -1
    fmt=lambda v: format(v,'.8g')
    result.append(dict(variant=r['variant'],higher_mvp_insomnia_allele=r['counted_allele'] if s==1 else r['other_allele'],comparison_allele=r['other_allele'] if s==1 else r['counted_allele'],nearest_gene_body_positional=r['nearest_gene_body_positional'],mvp_insomnia_or_approx=fmt(math.exp(abs(float(r['MVP_insomnia_log_OR_aligned_from_rounded_OR'])))),mvp_insomnia_p=r['MVP_insomnia_p'],hfrs_beta=fmt(s*float(r['HFRS_beta_aligned'])),hfrs_se=r['HFRS_se'],hfrs_p=r['HFRS_p'],fi_beta=fmt(s*float(r['FI_beta_aligned'])),fi_p=r['FI_p'],ffs_beta=fmt(s*float(r['FFS_beta_aligned'])),ffs_p=r['FFS_p'],ukb_insomnia_beta=fmt(s*float(r['UKB_insomnia_beta_aligned'])),ukb_insomnia_p=r['UKB_insomnia_p'],all_five_nominal=r['all_five_nominal'],reference_alleles=r['reference_alleles'],in_original_15=r['in_original_15']))
with Path('outputs/22_candidate_risk_direction_table.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(result)
out=['# Twenty-two candidates: aligning the estimated risk direction','', 'This table re-expresses the existing selected 22-variant screen using the allele associated with higher estimated MVP insomnia odds as the counted allele. The other allele is the specific comparison allele from the harmonized input, not all possible alternatives for a multiallelic rsID. Each row reflects an association estimate conditional on the original source model; the modest per-allele odds ratio is not absolute risk, does not establish causality, and cannot be interpreted as an individual prediction. Reversing a biallelic contrast makes the HFRS beta positive for these 22 because their original MVP and HFRS directions already agree. The MVP odds ratios are approximate because their source odds ratios were rounded before log transformation.', '', '| Variant | Higher-MVP-insomnia allele / comparator | Nearest gene body | MVP insomnia OR (approx.) | HFRS beta (SE) | FI beta | FFS beta |', '|---|---|---|---:|---:|---:|---:|']
for r in result:
 out.append(f"| {r['variant']} | {r['higher_mvp_insomnia_allele']} / {r['comparison_allele']} | {r['nearest_gene_body_positional']} | {float(r['mvp_insomnia_or_approx']):.3f} | {float(r['hfrs_beta']):+.3f} ({float(r['hfrs_se']):.3f}) | {float(r['fi_beta']):+.4f} | {float(r['ffs_beta']):+.4f} |")
out.extend(['','All 22 have positive FI point estimates in this orientation; 21 have positive FFS estimates. These are signs of point estimates, not proof that all four traits are affected or that effects differ from zero. Source phenotype scales differ: the HFRS, FI, and FFS betas are not directly comparable, not probabilities, and should never be summed. Refer to the companion CSV for source p-values, reference allele strings and original selection membership.','', 'The single negative FFS point estimate is '+', '.join(r['variant'] for r in result if float(r['ffs_beta'])<0)+'. Its uncertainty must be evaluated using the original FFS estimate and p-value; a negative point estimate alone is not evidence of a genuine protective effect. All 22 were selected from prior cross-trait candidates using nominal MVP insomnia and HFRS significance. Therefore, the same-direction pattern cannot be treated as an unbiased estimate of replication or mechanistic sharing. Some source populations overlap or may overlap.','', 'Gene names are proximity labels, not proven target genes. The source allele alignment and assembly remain subject to the documented limitations, particularly multiallelic variants and the inferred FFS effect-allele convention. Candidate cohorts have FI direction inconsistencies; see [cohort analysis](six_leads_fi_cohort_comparison.md). See [candidate review](expanded_22_candidate_risk_gene_review.md) and [source screening](song124_mvp_hfrs_followup.md) for selection, provenance and limitations. This is a research aid, not a clinical score.',''])
Path('outputs/22_candidate_risk_direction_review.md').write_text('\n'.join(out))
print('Wrote',len(result),'rows; opposite FFS:',[(r['variant'],r['ffs_p']) for r in result if float(r['ffs_beta'])<0])
